fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64> {
    // Defensive: avoid potential usize overflow in capacity calculation.
    let total_len = a
        .len()
        .checked_add(b.len())
        .expect("length overflow when concatenating vectors");

    let mut res = Vec::with_capacity(total_len);
    res.extend_from_slice(a.as_slice());
    res.extend_from_slice(b.as_slice());
    res
}

